// --- 4. 日誌工具 (Lab Logger) ---
function logLab(tag, message, level = 'info') {
  const container = document.getElementById('labLogContainer');
  if (!container) return;

  const now = Date.now();
  const elapsed = labState.sceneStartTime ? now - labState.sceneStartTime : 0;
  const timeFormatted = `+${elapsed}ms`.padStart(7, ' ');

  const entry = document.createElement('div');
  entry.className = `lab-log-entry ${level}`;
  entry.innerHTML = `<span class="lab-log-time">${timeFormatted}</span><span class="lab-log-tag">[${escapeHtml(tag)}]</span><span>${escapeHtml(message)}</span>`;
  container.appendChild(entry);
  container.scrollTop = container.scrollHeight;
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// --- 5. 畫面重設 (Reset & Cleanup Strategy - Zero Memory Leak) ---
function resetLab() {
  if(typeof clearGladiatorPresentationState==='function')clearGladiatorPresentationState();
  if(typeof clearSageSamplingIndicators==='function')clearSageSamplingIndicators();
  renderSageLabHud([{id:'mock-warrior',name:'亞瑟',role:'warrior',hp:120,maxHp:120},{id:'mock-mage',name:'梅林',role:'mage',hp:80,maxHp:80}]);
  sfxManager.stopAll();
  if(typeof bgmManager!=='undefined')bgmManager.reset();
  if (labState.activeController) {
    labState.activeController.abort();
    labState.activeController = null;
  }

  // Hide all overlays
  const overlays = [
    elements.chestPresentationOverlay,
    elements.trapPresentationOverlay,
    elements.floorIntroOverlay,
    elements.gameStartOverlay,
    elements.stageCinematicBanner,
    elements.screenTransitionCurtain,
    elements.equipDropModal,
    elements.combatActionBanner
  ];
  overlays.forEach(el => {
    if (el) {
      el.classList.add('hidden');
      el.classList.remove('enter', 'exit');
    }
  });

  // Hide discovery sections
  const evCard = document.getElementById('eventCardBox');
  if (evCard) {
    evCard.classList.add('hidden');
    evCard.classList.remove('is-shop-event');
    evCard.style.display = 'none';
  }
  if (elements.chestDiscoverySection) {
    elements.chestDiscoverySection.classList.add('hidden');
    elements.chestDiscoverySection.classList.remove('enter', 'exit');
    elements.chestDiscoveryStory.replaceChildren();
    elements.chestDiscoveryStory.classList.remove('dimmed');
  }
  if (elements.chestInteractionArea) {
    elements.chestInteractionArea.classList.add('hidden');
    elements.chestInteractionArea.classList.remove('enter');
  }
  if (elements.btnOpenChest) {
    elements.btnOpenChest.disabled = true;
    elements.btnOpenChest.classList.remove('ready', 'loading');
  }
  if (elements.presentationChestVisual) {
    elements.presentationChestVisual.replaceChildren();
    elements.presentationChestVisual.classList.remove('is-shaking', 'is-open');
  }
  if (elements.presentationRewardContent) {
    elements.presentationRewardContent.classList.add('hidden');
    elements.presentationRewardContent.classList.remove('enter');
  }

  if (elements.trapDiscoverySection) {
    elements.trapDiscoverySection.classList.add('hidden');
    elements.trapDiscoverySection.classList.remove('enter', 'exit');
    elements.trapDiscoveryStory.replaceChildren();
  }
  if (elements.trapVictimsContainer) {
    elements.trapVictimsContainer.replaceChildren();
  }

  if (elements.prologuePresBody) {
    elements.prologuePresBody.replaceChildren();
  }

  // Hide view panels
  document.getElementById('labMockHud')?.classList.remove('hidden');
  if (elements.views.statusLab) {
    elements.views.statusLab.classList.add('hidden');
    elements.views.statusLab.classList.remove('active');
  }
  if (elements.views.event) elements.views.event.classList.add('hidden');
  if (elements.views.route) elements.views.route.classList.add('hidden');
  if (elements.views.prologue) elements.views.prologue.classList.add('hidden');
  document.getElementById('p8LabLog')?.remove();

  // Reset body & stage classes
  document.body.classList.remove('presentation-chest-active', 'presentation-trap-active', 'presentation-floor-active');
  const stage = document.getElementById('labStage');
  if (stage) {
    stage.classList.remove('presentation-chest-active');
  }

  // Reset Mock HUD HP
  updateMockHudHp('mock-warrior', 120, 120);
  updateMockHudHp('mock-mage', 80, 80);

  // Clear presentation manager
  // Clean up combat presentation stage
  const combatStage = document.getElementById('presentationCombatStage');
  if (combatStage) {
    combatStage.replaceChildren();
    combatStage.classList.remove('is-active', 'is-exiting');
  }

  // Ensure unopened chest visual is initialized so it never disappears before open
  if (elements.chestVisualStage && typeof getChestSvgMarkup === 'function') {
    elements.chestVisualStage.innerHTML = getChestSvgMarkup();
  }

  // Reset Dev Assert panel
  const exp = document.getElementById('labAssertExpected');
  const disp = document.getElementById('labAssertDisplayed');
  const delta = document.getElementById('labAssertDelta');
  const warn = document.getElementById('labAssertWarning');
  if (exp) exp.textContent = '--';
  if (disp) disp.textContent = '--';
  if (delta) delta.textContent = '--';
  if (warn) warn.style.display = 'none';

  logLab('RESET', 'Stage cleanly reset. All timers, DOM nodes and overlays restored.');
}

function updateLabAssertion(step) {
  if (!step) return;
  const exp = document.getElementById('labAssertExpected');
  const disp = document.getElementById('labAssertDisplayed');
  const delta = document.getElementById('labAssertDelta');
  const warn = document.getElementById('labAssertWarning');
  const expected = step.finalDamage !== undefined ? step.finalDamage : (step.damage || 0);
  const displayed = expected;
  const hpDelta = (step.targetHpBefore !== undefined && step.targetHpAfter !== undefined) ? (step.targetHpBefore - step.targetHpAfter) : expected;
  if (exp) exp.textContent = expected;
  if (disp) disp.textContent = displayed;
  if (delta) delta.textContent = hpDelta;
  if (warn) warn.style.display = (expected !== displayed) ? 'block' : 'none';
}

function updateMockHudHp(playerId, hp, maxHp) {
  const chip = document.querySelector(`.lab-mock-player-chip[data-player-id="${playerId}"]`);
  if (!chip) return;
  const hpEl = chip.querySelector('.lab-mock-player-hp');
  if (hpEl) hpEl.textContent = `HP: ${hp}/${maxHp}`;
}

// Lab projects production snapshots only; it never invents presentation outcomes.
window.applyHpSnapshot = snapshot => {
  window.roomState = mergePresentationSnapshot(window.roomState,snapshot);
  for (const player of snapshot.players || []) {
    updateMockHudHp(player.id, player.hp, player.maxHp);
    const chip=[...document.querySelectorAll('.lab-mock-player-chip')].find(n=>n.dataset.playerId===player.id);
    if(chip){const resource=chip.querySelector('.combat-resource-summary');if(resource)resource.textContent=player.resourceSummary||'';syncPortraitStatusFx(player,chip.querySelector('.lab-sage-portrait'));}
    if(chip&&document.body.classList.contains('lab-battlefield-preview')){
      const portrait=chip.querySelector('.lab-sage-portrait');
      const descriptor=resolveBattlePortrait(player);const image=portrait?.querySelector('img');if(image&&descriptor.src)image.src=descriptor.src;
      syncPhase5LabMinions(player,chip);
    }
  }
  for(const enemy of snapshot.enemies||[]){const node=[...document.querySelectorAll('.lab-battlefield-enemy')].find(n=>n.dataset.enemyId===enemy.instanceId);if(node)node.querySelector('small').textContent=`HP ${enemy.hp}/${enemy.maxHp}`;}
};
// Existing lab fixtures exercise the production renderer on a single HUD, not
// on the retired cinematic result cards. Fixture aliases are normalized here.
async function playPhase5LabFixture(fixture,context,fixtureId) {
  document.body.classList.add('lab-battlefield-preview');
  const enemyRow=document.createElement('div');enemyRow.className='lab-battlefield-enemies';document.getElementById('labStage').appendChild(enemyRow);
  const steps=structuredClone(fixture.steps||[]);
  for(const [stepIndex,step] of steps.entries())for(const [index,result] of (step.results||[]).entries()){
    Object.assign(result,structuredClone(PHASE5_LAB_RESULT_CONTRACTS[fixtureId]?.[stepIndex]?.[index]||{}));
  }
  const normalize=snapshot=>{
    if(!snapshot)return;
    if(!snapshot.enemies?.length&&snapshot.monster)snapshot.enemies=[snapshot.monster];
    for(const [i,e] of (snapshot.enemies||[]).entries())e.instanceId||='lab-enemy-'+i;
    if(snapshot.monster)snapshot.monster.instanceId||=snapshot.enemies?.[0]?.instanceId;
    if(snapshot.arena&&snapshot.monster)snapshot.arena.enemyId||=snapshot.monster.instanceId;
  };
  for(const step of steps){
    normalize(step.hpSnapshotBefore);normalize(step.hpSnapshot);
    const id=step.targetEnemyId||step.hpSnapshotBefore?.monster?.instanceId;
    if(step.sourceId==='monster')step.sourceId=id;
    if(step.targetId==='monster'){step.targetId=id;step.targetEnemyId=id;}
    for(const result of step.results||[]){normalize(result.hpSnapshot);if(result.targetId==='monster'){result.targetId=id;result.targetEnemyId=id;if(result.targetBefore)result.targetBefore.instanceId=id;if(result.targetAfter)result.targetAfter.instanceId=id;}
    }
  }
  const initial=steps[0]?.hpSnapshotBefore;if(!initial){enemyRow.remove();return;}
  appliedBattleResults.clear();window.roomState=structuredClone(initial);renderSageLabHud(initial.players||[]);
  for(const enemy of initial.enemies||[]){
    const node=document.createElement('div');node.className='battle-enemy-slot lab-battlefield-enemy';node.dataset.enemyId=enemy.instanceId;
    const visual=document.createElement('div');visual.className='enemy-sprite-wrap';const image=document.createElement('img');image.src=resolveBattlePortrait({...enemy,avatar:enemy.avatar||steps[0].monsterAvatar,entityType:'monster'}).src;image.alt=enemy.name||'';visual.appendChild(image);node.appendChild(visual);
    const hp=document.createElement('small');hp.textContent=`HP ${enemy.hp}/${enemy.maxHp}`;node.appendChild(hp);enemyRow.appendChild(node);
  }
  syncEnemyArenaVisual(initial.arena||null);
  try{
    await Promise.all([...enemyRow.querySelectorAll('img'),...document.querySelectorAll('#labMockHud img')].map(image=>image.decode().catch(error=>{throw new Error('Lab image unavailable: '+image.src,{cause:error});})));
    for(const step of steps){if(context.signal.aborted)return;
    if(['boss_action','enemy_mechanic'].includes(step.type))await playEnemyMechanicPresentation(step,context);
    else if(['status_cleanup','kill','overheal_cleanup'].includes(step.type))await withBattlefieldSkillStage(step,context,async s=>{await s.resolveResults();});
    else await playBattlefieldPlayerPresentation(step,{...context,battlefield:true});
  }}
  finally{
    enemyRow.remove();
    // A cancelled playback may finish after its replacement has already
    // mounted. It must not clear the new playback's battlefield styling.
    if(!document.querySelector('.lab-battlefield-enemies')){
      syncEnemyArenaVisual(null);document.body.classList.remove('lab-battlefield-preview');
    }
  }
}
function syncPhase5LabMinions(player,chip){
  let hud=chip.querySelector('.lab-minion-hud');
  if(!hud){hud=document.createElement('div');hud.className='lab-minion-hud';chip.appendChild(hud);}
  hud.replaceChildren();
  for(const [index,minion] of (player.minions||[]).slice(0,3).entries()){
    const image=document.createElement('img');image.dataset.minionId=minion.id;
    const src=resolveBattlePortrait({...minion,minionIndex:minion.minionIndex||index+1,entityType:'minion'}).src;
    image.src=window.assetRegistry?window.assetRegistry.resolvePath(src):src;image.alt=minion.name||minion.type;hud.appendChild(image);
  }
}
function renderSageLabHud(players){
  const party=document.querySelector('#labMockHud .lab-mock-party');if(!party)return;
  party.replaceChildren();
  for(const p of players){
    const chip=document.createElement('div');chip.className='lab-mock-player-chip teammate-card';chip.dataset.playerId=p.id;
    chip.innerHTML='<div class="lab-sage-portrait teammate-avatar-wrap">'+battlePortraitHtml(p,'presentation-support-image')+'</div><span class="lab-mock-player-hp"></span><div class="combat-resource-summary"></div><div class="floating-text-container"></div>';
    party.appendChild(chip);updateMockHudHp(p.id,p.hp,p.maxHp);chip.querySelector('.combat-resource-summary').textContent=p.resourceSummary||'';
    syncPortraitStatusFx(p,chip.querySelector('.lab-sage-portrait'));
    syncPhase5LabMinions(p,chip);
  }
}

